corners=['TL','TR','BR','BL']
f1={'TL':'tri','TR':'star','BR':'circ','BL':'sq'}
def rot(f): return {corners[(corners.index(k)+1)%4]:v for k,v in f.items()}
f=f1
for _ in range(4): f=rot(f)
arrow=(0+45*4)%360
opts={'A':({'TL':'tri','TR':'star','BL':'sq','BR':'circ'},180),'B':({'TL':'tri','TR':'star','BL':'sq','BR':'circ'},90),'C':({'TL':'sq','TR':'tri','BL':'circ','BR':'star'},180),'D':({'TL':'sq','TR':'tri','BL':'circ','BR':'star'},225)}
assert [k for k,v in opts.items() if v==(f,arrow)]==['A']
